import {catalog,conceptFlows,connections,standard,types,levels,inScope} from './store.mjs';
import {esc,url,heading,overviewModes,standardURL,tone,pill,list,empty,options,uniq} from './ui.mjs';
import {conceptNetwork} from './flow-network.mjs';

const domains=['수와 연산','변화와 관계','도형과 측정','자료와 가능성','활용과 탐구'];
const textMatches=(code,q)=>{const s=standard(code);return [code,s.title,s.statement,s.subject,s.band].join(' ').toLowerCase().includes(q.toLowerCase());};
const memberCodes=t=>t.stages.flatMap(s=>s.codes);
export async function flowOverview(p){
 const original=await conceptFlows(),scope=p.get('scope')||'all',allowed=c=>inScope(standard(c),scope);
 const flows={...original,strands:original.strands.map(t=>({...t,stages:t.stages.map(s=>({...s,codes:s.codes.filter(allowed),primary_codes:s.primary_codes.filter(allowed),related:s.related.filter(r=>allowed(r.code))}))}))};
 const scoped=catalog.standards.filter(s=>inScope(s,scope));flows.coverage={...flows.coverage,primary_assigned:scoped.length,total:scoped.length,by_level:Object.fromEntries(levels.map(l=>[l,scoped.filter(s=>s.level===l).length]))};
 const q=(p.get('q')||'').trim(),domain=p.get('domain')||'',subject=p.get('subject')||'';
 const matches=flows.strands.filter(t=>memberCodes(t).length>0).filter(t=>(!domain||t.domain===domain)&&(!subject||t.stages[2].codes.some(c=>standard(c).subject===subject))&&(!q||[t.title,t.question].join(' ').includes(q)||memberCodes(t).some(c=>textMatches(c,q))));
 const selected=matches.find(t=>t.id===p.get('strand'));
 const rawEvidence=selected?await connections():null;const evidence=rawEvidence?{...rawEvidence,relations:rawEvidence.relations.filter(r=>!r.from.startsWith('standard:')||!r.to.startsWith('standard:')||allowed(r.from.slice(9))&&allowed(r.to.slice(9)))}:null;
 const params={scope,mode:'flow',q,domain,subject,expanded:p.get('expanded')||'',flowNode:p.get('flowNode')||'',flowReach:p.get('flowReach')||''};
 const visibleCodes=new Set(matches.flatMap(t=>t.stages.flatMap((s,i)=>s.codes.filter(c=>i!==2||!subject||standard(c).subject===subject))));
 return heading('COMPLETE CONCEPT ATLAS','초·중·고 개념 연결 지도','선택한 학교급의 성취기준을 개념으로 묶었습니다. 학교급별 내용을 비교하고 기준 전체와 연결 근거를 펼쳐보세요.',`<a class="text-link" href="${url('overview',{mode:'structure'})}">공식 학교급 구조 보기 ↗</a>`)+overviewModes('flow')+
 `<div class="flow-coverage"><div><strong>${flows.coverage.primary_assigned}<small> / ${flows.coverage.total}</small></strong><span>성취기준 전체 분류</span></div><div><strong>${flows.coverage.concepts}</strong><span>개념 묶음</span></div><p>초등 <b>${flows.coverage.by_level['초등학교']}</b> · 중학교 <b>${flows.coverage.by_level['중학교']}</b> · 고등학교 <b>${flows.coverage.by_level['고등학교']}</b><small>주 개념은 기준마다 하나 · 여러 개념을 함께 다루는 기준은 추가 표시</small></p><a class="text-link" href="${url('overview',{...params,expanded:p.get('expanded')==='all'?'':'all',strand:selected?.id||''})}" data-keep-scroll>${p.get('expanded')==='all'?'기준 목록 접기':'모든 성취기준 펼치기'} ${p.get('expanded')==='all'?'−':'＋'}</a></div>`+
 `<form class="full-flow-search" data-filter="overview"><input type="hidden" name="mode" value="flow"><input type="hidden" name="domain" value="${esc(domain)}"><input type="hidden" name="expanded" value="${esc(params.expanded)}"><div class="search-input"><span aria-hidden="true">⌕</span><input type="search" name="q" value="${esc(q)}" placeholder="개념, 원문, 성취기준 코드 검색" aria-label="개념 흐름 검색"></div><button class="button primary">찾기</button><label>고등학교 과목<select name="subject" data-auto-flow>${options(uniq(catalog.standards.filter(s=>s.level==='고등학교').map(s=>s.subject)),subject,'모든 과목')}</select></label><label>개념 바로가기<select name="strand" data-flow-jump><option value="">개념 선택</option>${domains.map(d=>`<optgroup label="${esc(d)}">${flows.strands.filter(t=>t.domain===d).map(t=>`<option value="${t.id}" ${selected?.id===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</optgroup>`).join('')}</select></label></form>`+
 `<div class="flow-domain-tabs full-flow-domains" aria-label="개념 영역">${[['','전체 개념'],...domains.map(d=>[d,d])].map(([d,t])=>`<a href="${url('overview',{...params,domain:d})}" ${domain===d?'aria-current="true"':''}>${esc(t)}</a>`).join('')}<span>${matches.length}개 개념 · 포함 기준 ${visibleCodes.size}개</span>${q||domain||subject?`<a href="${url('overview',{mode:'flow'})}">필터 초기화</a>`:''}</div>`+
 (matches.length?`<div class="flow-map"><div class="flow-map-header" aria-hidden="true"><div>개념과 기준</div>${levels.map((l,i)=>`<div class="flow-school school-${i}"><span>0${i+1}</span><strong>${l}</strong><small>${['공식 학년군별 성취기준','1~3학년군 성취기준','과목별 성취기준'][i]}</small></div>`).join('')}</div>${matches.map(t=>row(t,p,params,selected?.id===t.id,evidence,flows)).join('')}</div>`:empty('일치하는 개념 또는 성취기준이 없습니다.','다른 개념 이름이나 성취기준 코드로 찾아보세요.'))+
 `<div class="flow-method"><p><strong>435개 전체를 포함한 개념 분류</strong> · ${esc(flows.classification)}</p><p>${esc(flows.interpretation)} 직접 분류된 기준과 다른 개념에서 이어지는 기초 연결을 구별해 표시합니다. 연결 선후와 과목 선택 순서는 각각의 조건을 확인하세요.</p><a href="${url('about')}">자료의 출처와 분석 범위 →</a></div>`;
}
function standardLink(code,concept,additional,q,foundation=false){
 const s=standard(code),matched=q&&textMatches(code,q);
 return `<a class="flow-member ${matched?'is-match':''}" href="${standardURL(code)}" data-standard="${esc(code)}" data-focus-key="${foundation?'related':'member'}:${concept}:${esc(code)}" ${foundation?'':`data-classification="${additional?'additional':'primary'}"`} aria-label="${esc(code+' '+s.title+' 상세 읽기')}"><span class="flow-member-code">${esc(code)} ${additional?'<em>함께 다룸</em>':''}</span><strong>${esc(s.title)}</strong><small>${esc(s.level==='고등학교'?s.subject:s.band)} · ${esc(s.domain)}</small></a>`;
}
function row(t,p,params,selected,evidence,flows){
 const rowURL=url('overview',{...params,strand:selected?'':t.id}),q=params.q,byId=new Map(flows.strands.map(g=>[g.id,g]));
 return `<section class="flow-row tone-${tone(t.domain)} ${selected?'is-selected':''}" id="flow-${t.id}" aria-labelledby="flow-title-${t.id}"><div class="flow-row-line"><div class="flow-topic"><span class="flow-domain">${esc(t.domain)}</span><h2 id="flow-title-${t.id}"><a href="${rowURL}" aria-expanded="${selected}" aria-controls="flow-detail-${t.id}" data-keep-scroll>${esc(t.title)}</a></h2><small>${memberCodes(t).length}개 기준 포함</small><a class="flow-expand" href="${rowURL}" aria-label="${esc(t.title)} ${selected?'연결 설명 접기':'연결 지도 보기'}" aria-expanded="${selected}" aria-controls="flow-detail-${t.id}" data-keep-scroll>${selected?'연결 접기 −':'성취기준 연결 ＋'}</a></div>${t.stages.map((stage,i)=>{
 const codes=stage.codes.filter(c=>i!==2||!params.subject||standard(c).subject===params.subject),own=new Set(stage.primary_codes),related=stage.related.filter(r=>i!==2||!params.subject||standard(r.code).subject===params.subject);
 const opened=params.expanded==='all'||q&&codes.some(c=>textMatches(c,q));
 return `<div class="flow-stage flow-stage-${i} ${codes.length?'':'no-direct-standards'}" role="group" aria-label="${levels[i]} ${esc(t.title)}"><span class="flow-mobile-level">${levels[i]}</span>${codes.length?`<h3>${esc(stage.headline)}</h3><p class="flow-member-preview">${codes.slice(0,2).map(c=>esc(standard(c).title)).join(' · ')}${codes.length>2?' 외':''}</p><details class="flow-members" data-open="members:${t.id}:${i}" ${opened?'open':''}><summary><span>성취기준 <b>${codes.length}</b>개 전체 보기</span><span>⌄</span></summary><div>${codes.map(c=>standardLink(c,t.id,!own.has(c),q)).join('')}</div></details>`:'<p class="no-direct-label">이 학교급에 직접 분류된 기준이 없습니다.</p>'}${!codes.length&&related.length?`<div class="flow-related-preview"><span>연결된 다른 개념</span><p>${uniq(related.map(r=>byId.get(r.concept).title)).slice(0,3).map(esc).join(' · ')}</p></div>`:''}${related.length?`<details class="flow-foundations" data-open="foundations:${t.id}:${i}"><summary>다른 개념에서 이어지는 기준 ${related.length}개 <span>↗</span></summary><p class="foundation-note">아래 기준은 다른 개념 묶음에 속하며, 이 개념과의 학교급 간 연결 기록이 있습니다.</p>${related.map(r=>`<div class="foundation-item"><span>${esc(byId.get(r.concept).title)}</span>${standardLink(r.code,t.id,false,'',true)}<a class="text-link" href="${url('connections',{code:r.code,relation:r.relation_ids[0]})}">실제 연결과 조건 보기 →</a></div>`).join('')}</details>`:''}</div>`;
 }).join('')}</div><div class="flow-detail" id="flow-detail-${t.id}" ${selected?'':'hidden'}>${selected?explanation(t,evidence,p,params,flows):''}</div></section>`;
}
function explanation(t,data,p,params,flows){
 const ids=new Set([...t.relation_ids,...t.external_relation_ids]),inside=new Set(t.relation_ids);
 const scope=p.get('edgeScope')||'all',code=p.get('edgeCode')||p.get('flowNode')||(standard(params.q)?params.q:'');
 const records=data.relations.filter(r=>ids.has(r.id)&&(!code||[r.from,r.to].includes('standard:'+code))&&(scope!=='within'||inside.has(r.id))&&(scope!=='between'||!inside.has(r.id))&&(scope!=='cross-school'||standard(r.from.slice(9)).level!==standard(r.to.slice(9)).level));
 const limit=Math.max(12,Number(p.get('edgeLimit'))||12),byId=new Map(flows.strands.map(g=>[g.id,g]));
 return `<div class="flow-detail-heading"><p class="eyebrow">${esc(t.title)} · 전체 연결</p><h3>${esc(t.question)}</h3></div>${conceptNetwork(t,data,p,params)}<div class="flow-neighbor-concepts"><span>다른 개념과 이어 보기</span>${t.related_concepts.map(g=>`<a href="${url('overview',{mode:'flow',strand:g.id})}">${esc(byId.get(g.id).title)} <small>${g.records}</small></a>`).join('')||'<p>다른 개념과의 연결 기록이 없습니다.</p>'}</div><form class="flow-edge-filters" data-filter="overview">${Object.entries({...params,strand:t.id,flowNode:p.get('flowNode')||'',flowReach:p.get('flowReach')||''}).map(([k,v])=>`<input type="hidden" name="${k}" value="${esc(v)}">`).join('')}<label>연결 범위<select name="edgeScope" data-auto-flow>${[['cross-school','학교급 사이의 연결'],['all','모든 연결'],['within','같은 개념 안의 연결'],['between','다른 개념과의 연결']].map(([v,title])=>`<option value="${v}" ${v===scope?'selected':''}>${title}</option>`).join('')}</select></label><label>연결을 확인할 기준<select name="edgeCode" data-auto-flow><option value="">이 개념의 모든 기준</option>${uniq([...memberCodes(t),...(code&&standard(code)?[code]:[])]).map(c=>`<option value="${esc(c)}" ${c===code?'selected':''}>${esc(c+' · '+standard(c).title)}</option>`).join('')}</select></label><button class="button">적용</button></form><div class="flow-evidence-count">조건에 맞는 연결 기록 <b>${records.length}</b>개 · ${Math.min(limit,records.length)}개 표시</div><div class="flow-evidence full-flow-evidence">${records.slice(0,limit).map(r=>{
 const from=standard(r.from.slice(9)),to=standard(r.to.slice(9));
 return `<article data-evidence="${esc(r.id)}"><div class="flow-evidence-meta">${pill(types[r.type])}<span>${esc(from.level)} ${r.type==='generalizes'?'→':'↔'} ${esc(to.level)} · ${inside.has(r.id)?'같은 개념 안':'다른 개념과 연결'} · ${esc(r.status)}</span></div><h4><a href="${standardURL(from.code)}">${esc(from.code)} · ${esc(from.title)}</a><span aria-hidden="true">${r.type==='generalizes'?'→':'↔'}</span><a href="${standardURL(to.code)}">${esc(to.code)} · ${esc(to.title)}</a></h4><p>${esc(r.rationale)}</p><p class="muted">연결 범위 · ${esc(r.scope)}</p>${r.additional_learning?.length?`<details class="flow-extra"><summary>추가로 필요한 학습</summary>${list(r.additional_learning)}</details>`:''}<a class="text-link" href="${url('connections',{code:from.code,relation:r.id})}">조건과 출처까지 읽기 →</a></article>`;
 }).join('')||'<p>이 조건에 기록된 연결이 없습니다. 연결 범위를 바꾸어 확인할 수 있습니다.</p>'}</div>${records.length>limit?`<a class="button flow-more-evidence" data-keep-scroll href="${url('overview',{...params,strand:t.id,edgeScope:scope,edgeCode:code,edgeLimit:limit+24})}">연결 ${Math.min(24,records.length-limit)}개 더 보기 ↓</a>`:''}`;
}
